class MeineListe {
   private ListenElement anfang; 

   MeineListe() {
      anfang = new Abschluss(); 
   }

   // Damit Einheitlichkeit mit Buch besteht: 
   // ersetzt boolean add()  
   public void addLast(DatenElement daten) {
      anfang = anfang.add(daten);
      // Rückgabe der add Methode (in ListenElement) 
      // ist der passende "nachfolger"; somit wird die Kette 
      // wieder hergestellt bzw. beibehalten. 
   }

   // Damit Einheitlichkeit mit Buch besteht 
   public void addFirst(DatenElement daten) {
      Knoten temp = new Knoten(daten); 
      temp.setNachfolger(anfang);
      anfang = temp; 
   }

   // Damit Einheitlichkeit mit Buch besteht, 
   // fügt vor dem Knoten mit DatenElement "vor" ein. 
   public void addBefore(DatenElement daten, DatenElement vor) {
      anfang = anfang.addBefore(daten, vor);
   }

   // Damit Einheitlichkeit mit Buch besteht: 
   // jetzt Rückgabetyp void
   public void entfernen(DatenElement daten) {
      anfang = anfang.entfernen(daten); 
      // Rückgabe der entfernen Methode (in ListenElement) 
      // ist der passende "nachfolger"; somit wird die Kette 
      // wieder hergestellt bzw. beibehalten. 
   }

   public boolean enthält(DatenElement daten) {
      return anfang.enthält(daten);
   }

   public int länge() { 
      return anfang.länge(); 
   }

   private String elementeAusgeben() {
      return anfang.ausgeben(); 
   }

   /**
    * Methode zur Stringdatstellung aller Elemente 
    * der Liste, sowie ihrer Länge. 
    */
   public String toString() {
      String ausgabe = "Die Liste ist "; 
      int länge = this.länge(); 
      ausgabe += länge; 
      ausgabe += " Elemente lang mit folgenden Elementen: ";
      ausgabe += elementeAusgeben();
      return ausgabe; 
   }
}

class Knoten extends ListenElement {

   ListenElement nachfolger; 
   DatenElement daten; 

   Knoten(DatenElement daten) {
      this.daten = daten;
   }

   public ListenElement add(DatenElement daten) {
      // nicht letzer Knoten, da nicht Abschluss 
      nachfolger = nachfolger.add(daten); //Rekursion
      return this; 
      // Rückgabe der entfernen Methode ist der passende 
      // "nachfolger"; somit wird die Kette wieder 
      // hergestellt bzw. beibehalten. 
   }

   public ListenElement addBefore(DatenElement daten, DatenElement vor) {
      if(this.daten.equals(vor)) {
         Knoten temp = new Knoten(daten); 
         temp.setNachfolger(this);
         return temp; 
      } else {
         nachfolger = nachfolger.addBefore(daten, vor); 
         return this; 
      }
   }

   public boolean enthält(DatenElement daten) {
      if(this.daten.equals(daten)) {
         return true; 
      } else {
         return nachfolger.enthält(daten); 
      }
   }

   public ListenElement entfernen(DatenElement daten) {
      if(this.daten.equals(daten)) {
         //selbst habe die Daten
         return nachfolger; // Knoten sagt mittels Rückgabe, 
         // dass er übersprungen werden muss 
      } else {
         nachfolger = nachfolger.entfernen(daten); 
         // Rückgabe der entfernen Methode 
         // ist der passende "nachfolger"; somit wird die Kette 
         // wieder hergestellt bzw. beibehalten. 
         return this; 
         // Kette aufwärts (Richtung anfang) wird beibehalten.
      }
   }

   public int länge() {
      if(nachfolger == null) {
         return 1; 
      } else {
         return nachfolger.länge() + 1; 
      }
   }

   public ListenElement getNachfolger() {
      return nachfolger;
   }

   public void setNachfolger(ListenElement nachfolger) {
      this.nachfolger = nachfolger;
   }

   public DatenElement getDaten() {
      return daten;
   }

   public void setDaten(DatenElement daten) {
      this.daten = daten;
   }

   public String ausgeben() {
      // "\n" ist ein Zeilenumbruch
      return "\n" + this.daten.toString() + "; " + nachfolger.ausgeben();
   }

   public boolean equals(Object otherObject) {
      if(otherObject.getClass().equals(Knoten.class)) {
         Knoten knoten = (Knoten) otherObject; 
         if(knoten.getDaten().equals(this.daten) && knoten.nachfolger == this.nachfolger) {
            return true; 
         }
      }
      return false;
   }
}

class Taxi implements DatenElement {

   private int autonummer;
   private String fahrerName; 

   //Konstruktor
   public Taxi(int autonummer, String fahrerName) {
      this.autonummer = autonummer;
      this.fahrerName = fahrerName;
   }

   public String getFahrerName() {
      return fahrerName;
   }

   public void setFahrerName(String fahrerName) {
      this.fahrerName = fahrerName;
   }

   public int getAutonummer() {
      return autonummer;
   }

   public void setAutonummer(int autonummer) {
      this.autonummer = autonummer;
   }

   public String toString() {
      return "Autonummer: " + autonummer + " Fahrername: " + fahrerName; 
   }


   public boolean equals2(DatenElement daten) {
      if(daten.getClass().equals(Taxi.class)) {
         Taxi taxi = (Taxi) daten;
         if(taxi.toString().equals(this.toString())) { 
            return true; 
         }
      } 
      return false;
   }

   public boolean equals(DatenElement daten) {
      if(daten.getClass().equals(Taxi.class)) {
         Taxi taxi = (Taxi) daten;
         if(taxi.fahrerName == this.fahrerName 
                  && taxi.autonummer == this.autonummer) { 
            return true; 
         }
      } 
      return false;
   }
}

interface DatenElement {

   public String toString();

   // Methode um sauber zu vergleichen, 
   // ob zwei Objekte wirklich gleich sind 
   public boolean equals(DatenElement daten); 
}

class Patient implements DatenElement {
   private String name;
   private String adresse;
   private String krankheit;
   private int alter;

   public Patient(String name, String adresse, String krankheit, int alter){
      this.name = name;
      this.adresse = adresse;
      this.krankheit = krankheit;
      this.alter = alter;
   }

   public String toString() {
      return "Name: " + name + "; Adresse: " + adresse + "; Krankheit: " + krankheit + "; Alter: " + alter + ";"; 
   }

   public boolean equals(DatenElement daten) {
      if(daten.getClass().equals(Patient.class)) {
         Patient patient = (Patient) daten;
         if(patient.toString().equals(this.toString())) { 
            return true; 
         }
      } 
      return false;
   }
}

class Abschluss extends ListenElement {

   public ListenElement add(DatenElement daten) {
      //ist schon letzter Knoten
      Knoten temp = new Knoten(daten); 
      temp.setNachfolger(this);
      return temp;
   }

   public ListenElement addBefore(DatenElement daten, DatenElement vor) {
      return this; 
   }

   public boolean enthält(DatenElement daten) {
      return false;
   }

   public ListenElement entfernen(DatenElement daten) {
    		return this; 
  	}

   public int länge() {
      return 0; 
   }

   /**
    * @inheritDoc
    */
   public String ausgeben() {
      return ""; 
   }
}

abstract class ListenElement {

   /**
    * Methode um ein weiteres ListenElement am Ende der 
    * Kette anzufügen.
    */
   public abstract ListenElement add(DatenElement daten);

   /**
    * Methode um ein weiteres ListenElement vor dem spezifizierten  
    * in der Kette einzufügen.
    */
   public abstract ListenElement addBefore(DatenElement daten, DatenElement vor);

   /**
    * Methode zur Überprüfung, ob ein spezifisches DatenElement 
    * in der nachfolgenden Kette enthalten ist 
    */
   public abstract boolean enthält(DatenElement daten); 

   /**
    * Methode zum Entfernen eines spezifischen DatenElements
    */
   public abstract ListenElement entfernen(DatenElement daten);

   /**
    * Methode zur berechnung der Anzahl 
    * an Elementen in der Kette
    */
   public abstract int länge(); 

   /**
    * Methode zur Stringdarstellung der ListenElemente
    */
   public abstract String ausgeben();


}

